mapper.select:
/* * isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper.selectVacAprvMngList : 휴가승인관리목록 조회 * 2023.06.21 수정 - Jeong.Won.Je */ SELECT AA.COPA_INDEX_SN AS COPA_INDEX_SN /** 번호(상담파티색인일련번호) **/ , COUNT(*) OVER() AS TOTAL_COUNT , C##RG.DEC_B64(CC.FLNM_ENCPT) AS APLCNT_NM /** 신청자명 **/ , AA.USER_ID AS APLCNT_ID /** 신청자아이디 **/ , SUBSTR(AA.VCATN_APLY_YMD, 1,4)||'-'||SUBSTR(AA.VCATN_APLY_YMD, 5,2)||'-'||SUBSTR(AA.VCATN_APLY_YMD, 7,2) AS VCATN_APLY_YMD /** 신청일(휴가신청일자) **/ , SUBSTR(AA.VCATN_BGNG_YMD, 1,4)||'-'||SUBSTR(AA.VCATN_BGNG_YMD, 5,2)||'-'||SUBSTR(AA.VCATN_BGNG_YMD, 7,2) AS VCATN_BGNG_YMD /** 휴가시작일 **/ , SUBSTR(AA.VCATN_END_YMD, 1,4)||'-'||SUBSTR(AA.VCATN_END_YMD, 5,2)||'-'||SUBSTR(AA.VCATN_END_YMD, 7,2) AS VCATN_END_YMD /** 휴가종료일 **/ , AA.APLY_SE_CD AS APLY_SE_CD /* 신청구분코드 */ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APLY_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APLY_SE_CD ) AS APLY_SE_CD_NM /* 신청구분(신청구분코드) */ , AA.VCATN_SE_CD AS VCATN_SE_CD /** 휴가유형(휴가구분코드) **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'VCATN_SE_CD' AND A1.CMMNS_CD_VALUE = AA.VCATN_SE_CD ) AS VCATN_SE_CD_NM /** 휴가유형(휴가구분코드이름) **/ , AA.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /** 상태(승인상태구분코드) **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_CD_NM /** 상태(승인상태구분코드이름) **/ , AA.SMS_SNDNG_YN AS SMS_SNDNG_YN /** 발송상태(SMS발송여부) **/ , DECODE(AA.APRV_STTS_SE_CD,'0','Y','N') AS APRV_YN /** 상태가 대기(1)일 경우 check **/ , CASE WHEN ((AA.APRV_STTS_SE_CD = '2' OR AA.APRV_STTS_SE_CD = '3') AND AA.SMS_SNDNG_YN = 'N') THEN 'Y' ELSE 'N' END AS MSG_YN /** 처리상태가 승인(2) or 반려(3) 이고 문자발송이 N인 경우 check **/ FROM AYC130 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.DEL_YN = 'N' AND AA.USER_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO(+) /* 종사자번호 */ AND CC.DEL_YN = 'N' /* 종사자 삭제여부 */
AND AA.APLY_SE_CD = #{aplySeCd}
AND AA.APRV_STTS_SE_CD = #{aprvSttsSeCd}
AND AA.VCATN_SE_CD = #{vcatnSeCd}
AND AA.USER_ID LIKE '%'||#{userId}||'%'
AND CC.FLNM_ENCPT = C##RG.ENC_B64(#{userNm})
AND CC.OGDP_DEPT_CD = #{deptCd}
AND TO_DATE(AA.VCATN_APLY_YMD || '000000', 'YYYYMMDDHH24MISS') >= TO_DATE(#{bgngYmd} || '000000', 'YYYYMMDDHH24MISS')
AND TO_DATE(AA.VCATN_APLY_YMD || '000000', 'YYYYMMDDHH24MISS') < TO_DATE(#{endYmd} || '000000', 'YYYYMMDDHH24MISS')+1
ORDER BY AA.VCATN_APLY_YMD DESC , AA.COPA_INDEX_SN DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /** 페이징 처리 **/

/* * isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper.selectVacAprvMngDetail : 휴가승인관리 상세 조회 * 2023.06.21 수정 - Jeong.Won.Je */ SELECT AA.COPA_INDEX_SN AS COPA_INDEX_SN /** 번호(상담파티색인일련번호) **/ , C##RG.DEC_B64(CC.FLNM_ENCPT) AS APLCNT_NM /** 신청자명 **/ , AA.USER_ID AS APLCNT_ID /** 신청자아이디 **/ , AA.APLY_SE_CD AS APLY_SE_CD /* 신청구분코드 */ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APLY_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APLY_SE_CD ) AS APLY_SE_CD_NM /* 신청구분(신청구분코드) */ , AA.VCATN_APLY_YMD AS VCATN_APLY_YMD /** 신청일(휴가신청일자) **/ , AA.VCATN_CS_CN AS VCATN_CS_CN /** 신청사유(휴가사유내용) **/ , '15' AS CNSLTNT_USE_PSBLTY_YRYC_DAYCNT /** 연차총일수 **/ , '1' AS CNSLTNT_USE_VCATN_DAYCNT /** 연차사용일수 **/ , AA.VCATN_BGNG_YMD AS VCATN_BGNG_YMD /** 휴가시작일 **/ , AA.VCATN_END_YMD AS VCATN_END_YMD /** 휴가종료일 **/ , TO_CHAR((TO_DATE(AA.VCATN_END_YMD,'YYYYMMDD')-TO_DATE(AA.VCATN_BGNG_YMD,'YYYYMMDD'))+1) AS VAC_PERIOD , AA.PLACE_NM AS PLACE_NM /** 행선지(장소명) **/ , AA.APLCNT_CTTPC_TELNO AS APLCNT_CTTPC_TELNO /** 비상연락처 **/ , AA.RJCT_CS_CN AS RJCT_CS_CN /** 반려사유 **/ , AA.VCATN_SE_CD AS VCATN_SE_CD /** 휴가유형(휴가구분코드) **/ , AA.TASKWK_REPRTS_WRT_TRGT_YN AS TASKWK_REPRTS_WRT_TRGT_YN /** 업무보고서 작성대상 **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'VCATN_SE_CD' AND A1.CMMNS_CD_VALUE = AA.VCATN_SE_CD ) AS VCATN_SE_CD_NM /** 휴가유형(휴가구분코드이름) **/ , AA.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /** 상태(승인상태구분코드) **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_CD_NM /** 상태(승인상태구분코드이름) **/ , AA.SMS_SNDNG_YN AS SMS_SNDNG_YN /** 발송상태(SMS발송여부) **/ FROM AYC130 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.USER_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO
AND AA.COPA_INDEX_SN = #{copaIndexSn}
AND AA.USER_ID = #{userId}

mapper.update:
/** * updateVacAprvMngBatch : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : 휴가승인관리 일괄 승인 */ UPDATE AYC130 AA /** 사이버1388휴가 **/ SET AA.APRV_STTS_SE_CD = '2' /** 승인(2) **/
, AA.LAST_MDFR_ID = #{loginId}
, AA.LAST_MDFCN_DT = SYSDATE WHERE 1=1 AND AA.APRV_STTS_SE_CD IN ('0') /** 대기(0) **/ AND AA.DEL_YN = 'N'

	   /**
        *  updateVacAprvBatch : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : selectVacAprvBatchList을 통해 조회된 휴가신청 데이터의 승인상태구분코드를 '대기' → '승인'으로 변경
        */
        UPDATE
                AYC130      T1      /* 사이버1388휴가 */
        SET
                T1.APRV_STTS_SE_CD        =       #{aprvCdValue}
                , T1.LAST_MDFR_ID         =       #{loginId}
                , T1.LAST_MDFCN_DT        =       SYSDATE
        WHERE   1=1
        AND     T1.COPA_INDEX_SN          =       #{COPA_INDEX_SN}

/**
*	updateVacAprvMng : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : 휴가승인관리 단건 수정
*/
	UPDATE
			AYC130		AA  /** 사이버1388휴가 **/
	SET
			AA.LAST_MDFR_ID		= #{loginId}
		,	AA.LAST_MDFCN_DT	= SYSDATE


		,	AA.VCATN_APLY_YMD	= #{VCATN_APLY_YMD}




		,	AA.VCATN_CS_CN		= #{VCATN_CS_CN}




		,	AA.VCATN_SE_CD		= #{VCATN_SE_CD}




		,	AA.VCATN_BGNG_YMD	= #{VCATN_BGNG_YMD}




		,	AA.VCATN_END_YMD	= #{VCATN_END_YMD}




		,	AA.PLACE_NM			= #{PLACE_NM}




		,	AA.APRV_STTS_SE_CD	= #{APRV_STTS_SE_CD}




		,	AA.RJCT_CS_CN		= #{RJCT_CS_CN}




		,	AA.TASKWK_REPRTS_WRT_TRGT_YN	= #{TASKWK_REPRTS_WRT_TRGT_YN}


	WHERE	1=1
		AND	AA.COPA_INDEX_SN	=	#{COPA_INDEX_SN}

mapper.select:
/* * SQL-ID : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper.selectVacAprvMngGw : 휴가일정 건수 조회 * 2023.06.22 수정 - Jeong.Won.Je */ WITH VIEW_VCATN_APLY_HISTB AS (
)
SELECT COUNT(*) AS CNT FROM SAA200 A /** 사용자 */ , SCA100 B /** 종사자 */ , CAC400 C /** 청소년사이버상담 휴가승인정보 */ WHERE 1=1
AND B.ERP_EMPLA_NO = C.REQ_ID /* 회원아이디 (ERP 사원번호) */ AND B.DEL_YN = 'N' /* 종사자 삭제여부 */ AND A.ENFSN_NO = B.ENFSN_NO /* 종사자번호 */ ORDER BY C.ESB_SEQ ASC

mapper.insert:
/* * SQL-ID : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper.insertVacAprvMngGw : 휴가일정 가져오기 일괄 등록 * 신청구분코드(APLY_SE_CD), 연계일련번호(LINK_SN) 추가 * 2023.06.22 수정 - Jeong.Won.Je */
INSERT INTO AYC130 ( COPA_INDEX_SN /* 상담파티색인일련번호 */ , VCATN_APLY_YMD /* 휴가신청일자 */ , APLY_SE_CD /* 신청구분코드 */ , VCATN_CS_CN /* 휴가사유내용 */ , VCATN_SE_CD /* 휴가구분코드 */ , VCATN_BGNG_YMD /* 휴가시작일자 */ , VCATN_END_YMD /* 휴가종료일자 */ , APLCNT_CTTPC_TELNO /* 신청자연락처전화번호 */ , VCATN_APLY_DAYCNT /* 휴가신청일수 */ , APRV_STTS_SE_CD /* 승인상태구분코드 */ , USER_ID /* 사용자아이디 */ , LINK_SN /* 연계일련번호 */ , FRST_RGTR_ID /* 최초등록자아이디 */ , FRST_REG_DT /* 최초등록일시 */ , LAST_MDFR_ID /* 최종수정자아이디 */ , LAST_MDFCN_DT /* 최종수정일시 */ )
WITH VIEW_VCATN_APLY_HISTB AS (
)
SELECT AYC130_SQ01.NEXTVAL AS COPA_INDEX_SN /* 상담파티색인일련번호 */ , T.* FROM ( SELECT C.HOLI_APP AS VCATN_APLY_YMD /* 휴가신청일자 */ , CASE C.HOLI_STATUS WHEN '0' THEN '01' WHEN '2' THEN '01' WHEN '9' THEN '02' ELSE NULL END AS APLY_SE_CD /* 신청구분코드 */ , C.HOLI_REASON AS VCATN_CS_CN /* 휴가사유내용 */ , CASE C.HOLI_DIV_1 WHEN 'ANNU' THEN '01' WHEN 'SICK' THEN '02' WHEN 'OFFI' THEN '03' WHEN 'REWA' THEN '06' ELSE '05' END AS VCATN_SE_CD /* 휴가구분코드 */ , C.HOLI_START_1 AS VCATN_BGNG_YMD /* 휴가시작일자 */ , C.HOLI_END_1 AS VCATN_END_YMD /* 휴가종료일자 */ , C.HOLI_HP AS APLCNT_CTTPC_TELNO /* 신청자연락처전화번호 */ , C.HOLI_REQ_USE AS VCATN_APLY_DAYCNT /* 휴가신청일수 */ , '0' AS APRV_STTS_SE_CD /* 승인상태구분코드: 0 (대기) 로 고정 */ , A.USER_ID AS USER_ID /* 사용자아이디 */ , C.ESB_SEQ AS LINK_SN /* 연계시퀀스 */ , #{RGTR_ID} /* 최초등록자아이디 */ , SYSDATE /* 최초등록일시 */ , #{RGTR_ID} /* 최종수정자아이디 */ , SYSDATE /* 최종수정일시 */ FROM SAA200 A /** 사용자 */ , SCA100 B /** 종사자 */ , CAC400 C /** 청소년사이버상담 휴가승인정보 */ WHERE 1=1
AND B.ERP_EMPLA_NO = C.REQ_ID /* 회원아이디 (ERP 사원번호) */ AND B.DEL_YN = 'N' /* 종사자 삭제여부 */ AND A.ENFSN_NO = B.ENFSN_NO /* 종사자번호 */ ORDER BY C.ESB_SEQ ASC
) T

mapper.select:
	/*
     * isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper.selectBfeVcatnAplyMaxIndex : 동일한 휴가신청건 조회
     * 2023.06.21 추가 - Jeong.Won.Je
     */
		SELECT  
		      MAX(COPA_INDEX_SN)
		FROM
		      AYC130
		WHERE 1=1
		AND   APLY_SE_CD          =   '01'
		AND   APRV_STTS_SE_CD     =   '2'
		AND   DEL_YN              =   #{DEL_YN}
		AND   USER_ID             =   #{APLCNT_ID}
		AND   VCATN_SE_CD         =   #{VCATN_SE_CD}
		AND   VCATN_BGNG_YMD      =   #{VCATN_BGNG_YMD}
		AND   VCATN_END_YMD       =   #{VCATN_END_YMD}

		AND   VCATN_APLY_YMD      <=  #{VCATN_APLY_YMD}

mapper.update:
	/*
     * isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper.updateRtrcnRelataDelRpcs : 동일한 휴가신청건 삭제 처리
     * 2023.06.21 추가 - Jeong.Won.Je
     */
		UPDATE
		        AYC130
		SET
		        DEL_YN              =   #{DEL_YN}
		        , LAST_MDFR_ID      =   #{loginId}
		        , LAST_MDFCN_DT     =   SYSDATE
		WHERE   1=1
		AND     COPA_INDEX_SN       =   #{copaIndexSn}
